(window.__APPSRC=window.__APPSRC||{})["xmvkq4zed--zg-sj-prepa-chir-j2-ide"]="{\n \"app\": \"xmvkq4zed\",\n \"id\": \"zg-sj-prepa-chir-j2-ide\",\n \"titre\": \"Préparation D.E (J) · J2 Chirurgie IDE\",\n \"session\": \"J\",\n \"annee\": 2026,\n \"nq\": 57,\n \"nsuj\": 1,\n \"origines\": [\n  {\n   \"fichier\": \"prepa-de-2026/REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n   \"sha256\": \"45110ca169c7b815e8c5983cb6aa915440763cce1306bb015109584afb42df7f\"\n  }\n ],\n \"antennes\": [\n  {\n   \"name\": \"J DE PRÉPARATION AU D.E\",\n   \"slug\": \"j-preparation-de\",\n   \"session\": \"J\",\n   \"annee\": 2026,\n   \"existe\": true,\n   \"sujets\": [\n    {\n     \"name\": \"J Chirurgie · Prépa D.E J2 (IDE)\",\n     \"slug\": \"prepa-chir-j2-ide\",\n     \"pages\": \"\",\n     \"count\": 57,\n     \"session\": \"J\",\n     \"annee\": 2026,\n     \"matiere\": \"Chirurgie\",\n     \"source\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n     \"questions\": [\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__0\",\n       \"num\": \"1\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE N°1 (réponse juste + 1 pt ; réponse fausse et sans réponse 0 pt). Stagiaire au service de chirurgie du CHR de MAN, vous recevez pendant votre permanence l'enfant Kapen, 3 ans, pesant 14 kg, présentant une insuffisance cardiaque pour brûlure. Le bilan des lésions met en évidence : une brûlure de la face ; une brûlure de la cuisse gauche jusqu'à la jambe homolatérale ; une brûlure de la main gauche ; une brûlure de la moitié inférieure du tronc antérieur.\",\n       \"text\": \"L'infirmier vous demande de l'aider à évaluer l'étendue de la brûlure selon la table de Lund et Browder. Indiquer la formule générale de Baxter que vous appliquerez à Kapen à J2 parmi ces propositions.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"QJ2 = 4 X Pds (Kg) X SCB\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"QJ2 = 40 Kg X SCB\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"QJ2 = 80 Kg X SCB\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"QJ2 = 2 X Pds (Kg) X SCB\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. QJ2 = 2 X Pds (Kg) X SCB\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Règle de Baxter du cours : J1 = Poids (kg) × 4 × SCB ; J2 = ½ de QJ1. Diviser 4 × Pds × SCB par deux donne bien la formule générale QJ2 = 2 × Pds (kg) × SCB. « 4 × Pds × SCB » est la formule de J1 ; 40 kg et 80 kg ne correspondent pas au poids de Kapen (14 kg).\\n\\nSource : COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE (L1 IDE-SF), chapitre Brûlures, p. 85-101 (5.3 Réanimation hydroélectrolytique)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__1\",\n       \"num\": \"2\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE N°1 (réponse juste + 1 pt ; réponse fausse et sans réponse 0 pt). Stagiaire au service de chirurgie du CHR de MAN, vous recevez pendant votre permanence l'enfant Kapen, 3 ans, pesant 14 kg, présentant une insuffisance cardiaque pour brûlure. Le bilan des lésions met en évidence : une brûlure de la face ; une brûlure de la cuisse gauche jusqu'à la jambe homolatérale ; une brûlure de la main gauche ; une brûlure de la moitié inférieure du tronc antérieur.\",\n       \"text\": \"Indiquer parmi ces propositions la formule spécifique de Baxter applicable à l'enfant Kapen à J1.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"QJ1 = 4 X Pds X SCB\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"QJ1 = 2 X Pds X SCB\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"QJ1 = 28 Kg X SCB\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"QJ1 = 56 Kg X SCB\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. QJ1 = 56 Kg X SCB\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Formule spécifique = formule générale de J1 appliquée au poids de Kapen : 4 × 14 kg = 56 kg, d'où QJ1 = 56 kg × SCB. « 28 kg × SCB » (2 × 14) correspond à J2.\\n\\nSource : COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE (L1 IDE-SF), chapitre Brûlures, p. 85-101 (5.3)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__2\",\n       \"num\": \"3\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE N°1 (réponse juste + 1 pt ; réponse fausse et sans réponse 0 pt). Stagiaire au service de chirurgie du CHR de MAN, vous recevez pendant votre permanence l'enfant Kapen, 3 ans, pesant 14 kg, présentant une insuffisance cardiaque pour brûlure. Le bilan des lésions met en évidence : une brûlure de la face ; une brûlure de la cuisse gauche jusqu'à la jambe homolatérale ; une brûlure de la main gauche ; une brûlure de la moitié inférieure du tronc antérieur.\",\n       \"text\": \"Indiquer parmi ces propositions la surface corporelle brûlée au niveau du squelette axial de l'enfant Kapen.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"SCB = 44,5 %\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"SCB = 14,5 %\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"SCB = 29,5 %\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"SCB = 15 %\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"SCB = 30 %\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. SCB = 15 %\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Squelette axial = tête et tronc. Enfant de 3 ans → colonne 1-4 ans : tête 17 %, dont la face ≈ la moitié = 8,5 % ; tronc antérieur 13 %, dont la moitié inférieure = 6,5 %. Total : 8,5 + 6,5 = 15 %. Remarque : Le cours ne précise pas la part de la face ; elle est comptée ici comme la moitié de la tête (8,5 %), ce qui donne le résultat de la correction.\\n\\nSource : COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE (L1 IDE-SF), chapitre Brûlures, p. 85-101 (4.2 Table de Lund et Browder, colonne 1-4 ans)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__3\",\n       \"num\": \"4\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE N°1 (réponse juste + 1 pt ; réponse fausse et sans réponse 0 pt). Stagiaire au service de chirurgie du CHR de MAN, vous recevez pendant votre permanence l'enfant Kapen, 3 ans, pesant 14 kg, présentant une insuffisance cardiaque pour brûlure. Le bilan des lésions met en évidence : une brûlure de la face ; une brûlure de la cuisse gauche jusqu'à la jambe homolatérale ; une brûlure de la main gauche ; une brûlure de la moitié inférieure du tronc antérieur.\",\n       \"text\": \"Indiquer parmi ces propositions la surface corporelle brûlée au niveau du squelette appendiculaire de l'enfant Kapen.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"SCB = 15 %\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"SCB = 29,5 %\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"SCB = 44,5 %\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"SCB = 14 %\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"SCB = 30 %\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. SCB = 14 %\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Squelette appendiculaire = membres. Colonne 1-4 ans : une cuisse 6,5 % + une jambe 5 % + une main 2,5 % = 14 %.\\n\\nSource : COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE (L1 IDE-SF), chapitre Brûlures, p. 85-101 (4.2, colonne 1-4 ans)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__4\",\n       \"num\": \"5\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE N°1 (réponse juste + 1 pt ; réponse fausse et sans réponse 0 pt). Stagiaire au service de chirurgie du CHR de MAN, vous recevez pendant votre permanence l'enfant Kapen, 3 ans, pesant 14 kg, présentant une insuffisance cardiaque pour brûlure. Le bilan des lésions met en évidence : une brûlure de la face ; une brûlure de la cuisse gauche jusqu'à la jambe homolatérale ; une brûlure de la main gauche ; une brûlure de la moitié inférieure du tronc antérieur.\",\n       \"text\": \"Calculez la surface corporelle totale brûlée de l'enfant Kapen. Indiquer votre résultat parmi les propositions ci-dessous.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"SCB = 30 %\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"SCB = 44,5 %\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"SCB = 29 %\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"SCB = 15 %\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"SCB = 14,5 %\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. SCB = 29 %\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"SCB totale = squelette axial + squelette appendiculaire = 15 % + 14 % = 29 %.\\n\\nSource : COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE (L1 IDE-SF), chapitre Brûlures, p. 85-101 (4.2)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__5\",\n       \"num\": \"6\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE N°1 (réponse juste + 1 pt ; réponse fausse et sans réponse 0 pt). Stagiaire au service de chirurgie du CHR de MAN, vous recevez pendant votre permanence l'enfant Kapen, 3 ans, pesant 14 kg, présentant une insuffisance cardiaque pour brûlure. Le bilan des lésions met en évidence : une brûlure de la face ; une brûlure de la cuisse gauche jusqu'à la jambe homolatérale ; une brûlure de la main gauche ; une brûlure de la moitié inférieure du tronc antérieur.\",\n       \"text\": \"Ces événements se sont succédé lors de la brûlure de l'enfant Kapen. Classez-les par ordre chronologique de survenue : 1. Exsudation plasmatique ; 2. Anoxie tissulaire ; 3. Hypovolémie ; 4. Trouble de la perméabilité capillaire. Indiquer le résultat de votre classification parmi ces propositions.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"4-1-3-2\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"1-2-3-4\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"4-3-2-1\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"1-4-3-2\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. 4-1-3-2\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le cours décrit un cercle vicieux : exsudation plasmatique au niveau des plaies → fuite liquidienne → hypovolémie → anoxie tissulaire avec troubles de la perméabilité capillaire, qui entretiennent la fuite. La correction nationale place le trouble de la perméabilité capillaire en premier (c'est lui qui permet la fuite plasmatique), puis exsudation, hypovolémie et anoxie.\\n\\nSource : COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE (L1 IDE-SF), chapitre Brûlures, p. 85-101 (IV Physiopathologie, 4-1 Période initiale et schéma p. 88)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__6\",\n       \"num\": \"7\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE N°1 (réponse juste + 1 pt ; réponse fausse et sans réponse 0 pt). Stagiaire au service de chirurgie du CHR de MAN, vous recevez pendant votre permanence l'enfant Kapen, 3 ans, pesant 14 kg, présentant une insuffisance cardiaque pour brûlure. Le bilan des lésions met en évidence : une brûlure de la face ; une brûlure de la cuisse gauche jusqu'à la jambe homolatérale ; une brûlure de la main gauche ; une brûlure de la moitié inférieure du tronc antérieur.\",\n       \"text\": \"Sachant que votre condisciple était témoin de l'accident, indiquer parmi ces propositions trois actions à accomplir en sa qualité de premier secouriste.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Refroidissement de la victime à l'eau froide\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Rupture des phlyctènes\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Pansement avec topiques traditionnels\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Prévention du tétanos par injection de SAT\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Isolation thermique de la victime\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Couvrir la victime par un drap propre\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Refroidissement de la victime à l'eau froide ; E. Isolation thermique de la victime ; F. Couvrir la victime par un drap propre\",\n       \"answerLetters\": [\n        \"A\",\n        \"E\",\n        \"F\"\n       ],\n       \"explanation\": \"Premiers secours du cours : refroidissement par l'eau (15 °C pendant environ 15 min), couvrir la victime de champs stériles ou à défaut de draps propres, puis couverture d'isolation thermique. Rompre les phlyctènes, appliquer des topiques traditionnels ou injecter le SAT ne sont pas des gestes de secouriste (le SAT relève de la prise en charge hospitalière).\\n\\nSource : COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE (L1 IDE-SF), chapitre Brûlures, p. 85-101 (V Conduite à tenir, 5.1 Premiers secours)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__7\",\n       \"num\": \"8\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE N°1 (réponse juste + 1 pt ; réponse fausse et sans réponse 0 pt). Stagiaire au service de chirurgie du CHR de MAN, vous recevez pendant votre permanence l'enfant Kapen, 3 ans, pesant 14 kg, présentant une insuffisance cardiaque pour brûlure. Le bilan des lésions met en évidence : une brûlure de la face ; une brûlure de la cuisse gauche jusqu'à la jambe homolatérale ; une brûlure de la main gauche ; une brûlure de la moitié inférieure du tronc antérieur.\",\n       \"text\": \"Indiquer chez l'enfant Kapen les trois facteurs qui le prédisposent à des complications infectieuses parmi ces suggestions.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Les troubles de l'hémostase\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La translocation bactérienne\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La dépression immunitaire marquée\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"L'oedème pulmonaire\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"L'inhalation de fumées\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"La rupture de la barrière cutanée\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Les troubles de l'hémostase ; F. La rupture de la barrière cutanée\",\n       \"answerLetters\": [\n        \"A\",\n        \"F\"\n       ],\n       \"explanation\": \"La rupture de la barrière cutanée est la porte d'entrée principale des germes. Les troubles de l'hémostase (hypocoagulabilité de consommation, thrombopénie) font partie des perturbations du brûlé.\\n\\nSource : COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE (L1 IDE-SF), chapitre Brûlures, p. 85-101 (III Complications infectieuses, p. 97)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__8\",\n       \"num\": \"9\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE N°1 (réponse juste + 1 pt ; réponse fausse et sans réponse 0 pt). Stagiaire au service de chirurgie du CHR de MAN, vous recevez pendant votre permanence l'enfant Kapen, 3 ans, pesant 14 kg, présentant une insuffisance cardiaque pour brûlure. Le bilan des lésions met en évidence : une brûlure de la face ; une brûlure de la cuisse gauche jusqu'à la jambe homolatérale ; une brûlure de la main gauche ; une brûlure de la moitié inférieure du tronc antérieur.\",\n       \"text\": \"Relever selon le cas clinique les localisations de gravité des brûlures de l'enfant Kapen.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Le terrain\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Le genou gauche\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Les parties génitales\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La main gauche\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"La surface corporelle brûlée\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Le visage\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Le genou gauche ; D. La main gauche ; F. Le visage\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\",\n        \"F\"\n       ],\n       \"explanation\": \"Localisations de gravité : mains, visage, articulations, orifices naturels, périnée. Chez Kapen : la face (visage), la main gauche, et le genou gauche (articulation atteinte par la brûlure allant de la cuisse à la jambe). Le terrain et la SCB sont des facteurs de gravité, mais pas des localisations ; les parties génitales ne sont pas brûlées ici.\\n\\nSource : COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE (L1 IDE-SF), chapitre Brûlures, p. 85-101 (4.6 Localisation ; 3-3 Les brûlures graves)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__9\",\n       \"num\": \"10\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE N°1 (réponse juste + 1 pt ; réponse fausse et sans réponse 0 pt). Stagiaire au service de chirurgie du CHR de MAN, vous recevez pendant votre permanence l'enfant Kapen, 3 ans, pesant 14 kg, présentant une insuffisance cardiaque pour brûlure. Le bilan des lésions met en évidence : une brûlure de la face ; une brûlure de la cuisse gauche jusqu'à la jambe homolatérale ; une brûlure de la main gauche ; une brûlure de la moitié inférieure du tronc antérieur.\",\n       \"text\": \"Indiquer la valeur numérique de la quantité de liquide à perfuser à l'enfant Kapen à J1.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"QJ1 = 8,26\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"QJ1 = 16,24\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"QJ1 = 16,52\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"QJ1 = 8,4\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. QJ1 = 16,24\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"QJ1 = 4 × 14 × SCB. En prenant la SCB sous forme décimale (0,29) : 56 × 0,29 = 16,24. Avec la SCB en pourcentage (29), on obtient 1 624 mL. Remarque : La valeur 16,24 correspond à la SCB écrite 0,29 ; voir la question 14 pour l'unité.\\n\\nSource : COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE (L1 IDE-SF), chapitre Brûlures, p. 85-101 (5.3)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__10\",\n       \"num\": \"11\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE N°1 (réponse juste + 1 pt ; réponse fausse et sans réponse 0 pt). Stagiaire au service de chirurgie du CHR de MAN, vous recevez pendant votre permanence l'enfant Kapen, 3 ans, pesant 14 kg, présentant une insuffisance cardiaque pour brûlure. Le bilan des lésions met en évidence : une brûlure de la face ; une brûlure de la cuisse gauche jusqu'à la jambe homolatérale ; une brûlure de la main gauche ; une brûlure de la moitié inférieure du tronc antérieur.\",\n       \"text\": \"Indiquer la valeur numérique de la quantité de liquide à perfuser à l'enfant Kapen à J2.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"QJ2 = 16,52\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"QJ2 = 8,26\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"QJ2 = 8,4\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"QJ2 = 8,12\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. QJ2 = 8,12\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"QJ2 = ½ QJ1 = 16,24 / 2 = 8,12 (ou 2 × 14 × 0,29 = 8,12).\\n\\nSource : COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE (L1 IDE-SF), chapitre Brûlures, p. 85-101 (5.3 : J2 = ½ de QJ1)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__11\",\n       \"num\": \"12\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE N°1 (réponse juste + 1 pt ; réponse fausse et sans réponse 0 pt). Stagiaire au service de chirurgie du CHR de MAN, vous recevez pendant votre permanence l'enfant Kapen, 3 ans, pesant 14 kg, présentant une insuffisance cardiaque pour brûlure. Le bilan des lésions met en évidence : une brûlure de la face ; une brûlure de la cuisse gauche jusqu'à la jambe homolatérale ; une brûlure de la main gauche ; une brûlure de la moitié inférieure du tronc antérieur.\",\n       \"text\": \"Calculer l'indice de Baux de l'enfant Kapen, et indiquez votre réponse parmi ces propositions.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"IB = 32\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"IB = 47,5\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"IB = 47\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"IB = 29,5\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. IB = 47\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"L'indice de Baux additionne l'âge du brûlé et l'étendue de la brûlure (en %).\\n\\nSource : COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE (L1 IDE-SF), chapitre Brûlures, p. 85-101 (5-5 Pronostic, p. 92)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__12\",\n       \"num\": \"13\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE N°1 (réponse juste + 1 pt ; réponse fausse et sans réponse 0 pt). Stagiaire au service de chirurgie du CHR de MAN, vous recevez pendant votre permanence l'enfant Kapen, 3 ans, pesant 14 kg, présentant une insuffisance cardiaque pour brûlure. Le bilan des lésions met en évidence : une brûlure de la face ; une brûlure de la cuisse gauche jusqu'à la jambe homolatérale ; une brûlure de la main gauche ; une brûlure de la moitié inférieure du tronc antérieur.\",\n       \"text\": \"Indiquer parmi ces propositions le pronostic vital de l'enfant Kapen.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La guérison est infiniment probable\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La mort est quasi certaine\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Le brûlé a une chance sur deux de guérison\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. La guérison est infiniment probable\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Selon le cours : somme âge + étendue < 50 → guérison infiniment probable ; > 100 → mort quasi certaine ; entre 50 et 100 → une chance sur deux. L'indice de Kapen étant inférieur à 50 (32, ou même 47), la guérison est infiniment probable.\\n\\nSource : COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE (L1 IDE-SF), chapitre Brûlures, p. 85-101 (5-5 Pronostic)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__13\",\n       \"num\": \"14\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE N°1 (réponse juste + 1 pt ; réponse fausse et sans réponse 0 pt). Stagiaire au service de chirurgie du CHR de MAN, vous recevez pendant votre permanence l'enfant Kapen, 3 ans, pesant 14 kg, présentant une insuffisance cardiaque pour brûlure. Le bilan des lésions met en évidence : une brûlure de la face ; une brûlure de la cuisse gauche jusqu'à la jambe homolatérale ; une brûlure de la main gauche ; une brûlure de la moitié inférieure du tronc antérieur.\",\n       \"text\": \"En vous appuyant sur les formules, indiquer l'unité de QJ1 et QJ2 parmi ces propositions.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Kilogramme\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Centilitre\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Millilitre\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Litre\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Décilitre\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Litre\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"La règle de Baxter s'exprime en millilitres par kg et par % de SCB.\\n\\nSource : COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE (L1 IDE-SF), chapitre Brûlures, p. 85-101 (réanimation du premier jour, règle d'Evans : Q1 = 1 ml × Pkg × % ; 5.3 Baxter)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__14\",\n       \"num\": \"15\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE N°1 (réponse juste + 1 pt ; réponse fausse et sans réponse 0 pt). Stagiaire au service de chirurgie du CHR de MAN, vous recevez pendant votre permanence l'enfant Kapen, 3 ans, pesant 14 kg, présentant une insuffisance cardiaque pour brûlure. Le bilan des lésions met en évidence : une brûlure de la face ; une brûlure de la cuisse gauche jusqu'à la jambe homolatérale ; une brûlure de la main gauche ; une brûlure de la moitié inférieure du tronc antérieur.\",\n       \"text\": \"L'enfant Kapen devra bénéficier d'une surveillance infirmière très soutenue. Indiquer parmi ces éléments de surveillance celui qui est en rapport avec la réanimation hydroélectrolytique.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La respiration\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Le pouls\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La température\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"L'alimentation\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"La diurèse\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"E. La diurèse\",\n       \"answerLetters\": [\n        \"E\"\n       ],\n       \"explanation\": \"La diurèse est le reflet direct de l'efficacité du remplissage : le cours précise que « la diurèse surtout sera suivie d'heure en heure » (sonde urinaire à ballonnet). Pouls, température et respiration se surveillent aussi, mais ne sont pas spécifiques de la réanimation hydroélectrolytique.\\n\\nSource : COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE (L1 IDE-SF), chapitre Brûlures, p. 85-101 (La surveillance, p. 94)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__15\",\n       \"num\": \"16\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE N°2. Stagiaire au CHR de MAN, pendant votre permanence, alors que l'infirmier s'est retiré pour sa pause déjeuner, vous recevez monsieur Gbê. Voici les faits rapportés par celui-ci à l'interrogatoire : « Docteur, depuis près de dix jours je ne fais pas de selle ni de vent. En tout cas je sens un inconfort au ventre avec des douleurs vives. Vraiment docteur aidez-moi, ça ne va pas, je ne veux pas mourir ! » s'exclame-t-il tout en larmes.\",\n       \"text\": \"Selon les faits rapportés par M. Gbê, indiquer votre première conduite à tenir vis-à-vis de celui-ci parmi les propositions suivantes.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Informer l'infirmier\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Examiner le malade\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Prendre les constantes\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Préparation psychologique\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Préparation psychologique\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"M. Gbê est en larmes et dit qu'il a peur de mourir : la première conduite est de le préparer psychologiquement (le calmer, diminuer sa peur) avant l'examen et la prise des constantes.\\n\\nSource : licence 2 ide, Fractures, 9.2.2 Soins préopératoires ; Cours de chirurgie traumatique et digestif, diapo 260 (« préparation psychologique : diminuer la peur »)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__16\",\n       \"num\": \"17\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE N°2. Stagiaire au CHR de MAN, pendant votre permanence, alors que l'infirmier s'est retiré pour sa pause déjeuner, vous recevez monsieur Gbê. Voici les faits rapportés par celui-ci à l'interrogatoire : « Docteur, depuis près de dix jours je ne fais pas de selle ni de vent. En tout cas je sens un inconfort au ventre avec des douleurs vives. Vraiment docteur aidez-moi, ça ne va pas, je ne veux pas mourir ! » s'exclame-t-il tout en larmes.\",\n       \"text\": \"Indiquer deux contenus de cette première conduite tenue plus haut parmi ces propositions.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Inspecter le patient\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Mettre le malade en confiance\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Inscrire les constantes dans le dossier\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Rassurer le malade\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Appel téléphonique de l'infirmier\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Mettre le malade en confiance ; D. Rassurer le malade\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"La préparation psychologique consiste à mettre le malade en confiance et à le rassurer. Inspecter, inscrire les constantes ou appeler l'infirmier sont d'autres actes.\\n\\nSource : licence 2 ide, 9.2.2 Soins préopératoires (« le rassurer du mieux que l'on peut, l'assurer de votre présence »)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__17\",\n       \"num\": \"18\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE N°2. Stagiaire au CHR de MAN, pendant votre permanence, alors que l'infirmier s'est retiré pour sa pause déjeuner, vous recevez monsieur Gbê. Voici les faits rapportés par celui-ci à l'interrogatoire : « Docteur, depuis près de dix jours je ne fais pas de selle ni de vent. En tout cas je sens un inconfort au ventre avec des douleurs vives. Vraiment docteur aidez-moi, ça ne va pas, je ne veux pas mourir ! » s'exclame-t-il tout en larmes.\",\n       \"text\": \"Indiquer parmi ces propositions l'affection dont souffre M. Gbê.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Hernie étranglée\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Appendicite aiguë\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Occlusion intestinale\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Péritonite aiguë\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Occlusion intestinale\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"L'occlusion se définit par l'arrêt complet et persistant du transit des matières et des gaz, associé aux douleurs abdominales : c'est exactement ce que décrit M. Gbê (pas de selle ni de vent depuis 10 jours, douleurs vives). Rien n'évoque une hernie, une douleur de la fosse iliaque droite ou une contracture de péritonite.\\n\\nSource : licence 2 ide (Prise en charge infirmière des pathologies chirurgicales L2), Occlusions intestinales aiguës, p. 121-128 ; Cours de chirurgie traumatique et digestif, diapos 223-231\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__18\",\n       \"num\": \"19\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE N°2. Stagiaire au CHR de MAN, pendant votre permanence, alors que l'infirmier s'est retiré pour sa pause déjeuner, vous recevez monsieur Gbê. Voici les faits rapportés par celui-ci à l'interrogatoire : « Docteur, depuis près de dix jours je ne fais pas de selle ni de vent. En tout cas je sens un inconfort au ventre avec des douleurs vives. Vraiment docteur aidez-moi, ça ne va pas, je ne veux pas mourir ! » s'exclame-t-il tout en larmes.\",\n       \"text\": \"Indiquer selon le texte les signes fonctionnels de cette affection rapportés par M. Gbê parmi les propositions suivantes.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vomissement bilieux fécaloïde\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Douleur abdominale vive\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Météorisme abdominal\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Température élevée\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Douleur à la fosse iliaque droite\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Arrêt des matières et des gaz\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Douleur abdominale vive\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Les signes fonctionnels de l'occlusion sont : douleurs abdominales, vomissements, arrêt des matières et des gaz. Dans le texte, M. Gbê rapporte une douleur vive. Il ne parle ni de vomissements ni de fièvre ; le météorisme est un signe physique. Remarque : L'arrêt des matières et des gaz est aussi rapporté par le malade (« pas de selle ni de vent ») et le cours en fait le signe majeur ; la question n'accepte qu'une seule réponse et la correction retient la douleur.\\n\\nSource : licence 2 ide (Prise en charge infirmière des pathologies chirurgicales L2), Occlusions intestinales aiguës, p. 121-128 ; Cours de chirurgie traumatique et digestif, diapos 223-231 (III Syndrome occlusif : 3 signes fonctionnels)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__19\",\n       \"num\": \"20\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE N°2. Stagiaire au CHR de MAN, pendant votre permanence, alors que l'infirmier s'est retiré pour sa pause déjeuner, vous recevez monsieur Gbê. Voici les faits rapportés par celui-ci à l'interrogatoire : « Docteur, depuis près de dix jours je ne fais pas de selle ni de vent. En tout cas je sens un inconfort au ventre avec des douleurs vives. Vraiment docteur aidez-moi, ça ne va pas, je ne veux pas mourir ! » s'exclame-t-il tout en larmes.\",\n       \"text\": \"Indiquer parmi ces propositions un signe physique de cette affection que vous pouviez rechercher chez M. Gbê.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vomissement bilieux fécaloïde\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Douleur abdominale vive\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Arrêt des matières et des gaz\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Météorisme abdominal\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Température élevée\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Douleur à la fosse iliaque droite\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Météorisme abdominal\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Le cours décrit un seul signe physique de l'occlusion : le météorisme abdominal (augmentation du volume de l'abdomen). Vomissements, douleur et arrêt du transit sont des signes fonctionnels.\\n\\nSource : licence 2 ide (Prise en charge infirmière des pathologies chirurgicales L2), Occlusions intestinales aiguës, p. 121-128 ; Cours de chirurgie traumatique et digestif, diapos 223-231 (« Signe physique : c'est le météorisme abdominal »)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__20\",\n       \"num\": \"21\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE N°2. Stagiaire au CHR de MAN, pendant votre permanence, alors que l'infirmier s'est retiré pour sa pause déjeuner, vous recevez monsieur Gbê. Voici les faits rapportés par celui-ci à l'interrogatoire : « Docteur, depuis près de dix jours je ne fais pas de selle ni de vent. En tout cas je sens un inconfort au ventre avec des douleurs vives. Vraiment docteur aidez-moi, ça ne va pas, je ne veux pas mourir ! » s'exclame-t-il tout en larmes.\",\n       \"text\": \"Indiquer parmi ces propositions deux moyens dont vous disposez pour mettre en évidence ce signe physique.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Auscultation\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"L'inspection\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"L'ASP\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La palpation\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"L'interrogatoire\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. L'inspection ; D. La palpation\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"Le météorisme se voit à l'inspection (abdomen augmenté de volume, en cadre…) et se confirme à la palpation (paroi souple, tendue, élastique) et à la percussion (tympanisme). L'ASP est un examen complémentaire ; l'interrogatoire recueille des signes fonctionnels.\\n\\nSource : licence 2 ide (Prise en charge infirmière des pathologies chirurgicales L2), Occlusions intestinales aiguës, p. 121-128 ; Cours de chirurgie traumatique et digestif, diapos 223-231 (signe physique)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__21\",\n       \"num\": \"22\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE N°2. Stagiaire au CHR de MAN, pendant votre permanence, alors que l'infirmier s'est retiré pour sa pause déjeuner, vous recevez monsieur Gbê. Voici les faits rapportés par celui-ci à l'interrogatoire : « Docteur, depuis près de dix jours je ne fais pas de selle ni de vent. En tout cas je sens un inconfort au ventre avec des douleurs vives. Vraiment docteur aidez-moi, ça ne va pas, je ne veux pas mourir ! » s'exclame-t-il tout en larmes.\",\n       \"text\": \"En vous appuyant sur les signes rapportés par le malade, indiquer le siège de cette affection parmi les propositions suivantes.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"L'intestin grêle\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La fosse iliaque droite\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La fosse iliaque gauche\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Le côlon\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Le côlon\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Occlusion colique : début progressif, vomissements rares et tardifs, arrêt des matières et des gaz net, état longtemps conservé. M. Gbê a un arrêt du transit depuis 10 jours sans vomissements rapportés : tableau d'occlusion basse, du côlon.\\n\\nSource : licence 2 ide (Prise en charge infirmière des pathologies chirurgicales L2), Occlusions intestinales aiguës, p. 121-128 ; Cours de chirurgie traumatique et digestif, diapos 223-231 (V Diagnostic du siège : l'occlusion colique)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__22\",\n       \"num\": \"23\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE N°2. Stagiaire au CHR de MAN, pendant votre permanence, alors que l'infirmier s'est retiré pour sa pause déjeuner, vous recevez monsieur Gbê. Voici les faits rapportés par celui-ci à l'interrogatoire : « Docteur, depuis près de dix jours je ne fais pas de selle ni de vent. En tout cas je sens un inconfort au ventre avec des douleurs vives. Vraiment docteur aidez-moi, ça ne va pas, je ne veux pas mourir ! » s'exclame-t-il tout en larmes.\",\n       \"text\": \"Informé des résultats de vos investigations, l'infirmier vous demande de prescrire des examens complémentaires. Indiquer les examens radiologiques que vous pouvez prescrire à M. Gbê parmi ces propositions.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Numération formule sanguine\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"L'échographie abdominale\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"L'ASP\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Lavement baryté\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Ionogramme sanguin\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. L'ASP ; D. Lavement baryté\",\n       \"answerLetters\": [\n        \"C\",\n        \"D\"\n       ],\n       \"explanation\": \"Examens radiologiques de l'occlusion : l'ASP (niveaux hydroaériques) et le lavement baryté (précise le siège d'un obstacle colique). NFS et ionogramme sont des examens biologiques, pas radiologiques.\\n\\nSource : licence 2 ide (Prise en charge infirmière des pathologies chirurgicales L2), Occlusions intestinales aiguës, p. 121-128 ; Cours de chirurgie traumatique et digestif, diapos 223-231 (1.4 Signes radiologiques)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__23\",\n       \"num\": \"24\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE N°2. Stagiaire au CHR de MAN, pendant votre permanence, alors que l'infirmier s'est retiré pour sa pause déjeuner, vous recevez monsieur Gbê. Voici les faits rapportés par celui-ci à l'interrogatoire : « Docteur, depuis près de dix jours je ne fais pas de selle ni de vent. En tout cas je sens un inconfort au ventre avec des douleurs vives. Vraiment docteur aidez-moi, ça ne va pas, je ne veux pas mourir ! » s'exclame-t-il tout en larmes.\",\n       \"text\": \"Indiquer parmi ces propositions les résultats éventuels des examens radiologiques.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Désordre hydroélectrolytique\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Côlon partiellement injecté de baryte\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Niveau hydroaérique\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Hématocrite élevé\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Côlon totalement injecté\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Côlon partiellement injecté de baryte ; D. Hématocrite élevé\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"Au lavement baryté, en cas d'obstacle colique, la baryte bute sur l'obstacle : le côlon n'est que partiellement injecté. (Le côlon totalement injecté s'observe dans l'occlusion du grêle.)\\n\\nSource : licence 2 ide (Prise en charge infirmière des pathologies chirurgicales L2), Occlusions intestinales aiguës, p. 121-128 ; Cours de chirurgie traumatique et digestif, diapos 223-231 (1.3 Signes biologiques ; 1.4 Signes radiologiques)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__24\",\n       \"num\": \"25\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE N°2. Stagiaire au CHR de MAN, pendant votre permanence, alors que l'infirmier s'est retiré pour sa pause déjeuner, vous recevez monsieur Gbê. Voici les faits rapportés par celui-ci à l'interrogatoire : « Docteur, depuis près de dix jours je ne fais pas de selle ni de vent. En tout cas je sens un inconfort au ventre avec des douleurs vives. Vraiment docteur aidez-moi, ça ne va pas, je ne veux pas mourir ! » s'exclame-t-il tout en larmes.\",\n       \"text\": \"Indiquer le résultat de l'ionogramme sanguin parmi ces propositions.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Désordre hydroélectrolytique\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Côlon partiellement injecté de baryte\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Hématocrite élevé\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Côlon totalement injecté\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Niveau hydroaérique\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Désordre hydroélectrolytique\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'occlusion s'accompagne « toujours » de désordres hydroélectrolytiques : hypochlorémie, hyponatrémie, hypokaliémie… C'est ce que montre l'ionogramme. Les autres propositions sont des résultats radiologiques ou de la NFS.\\n\\nSource : licence 2 ide (Prise en charge infirmière des pathologies chirurgicales L2), Occlusions intestinales aiguës, p. 121-128 ; Cours de chirurgie traumatique et digestif, diapos 223-231 (1.2 Signes généraux ; 1.3 Signes biologiques)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__25\",\n       \"num\": \"26\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE N°2. Stagiaire au CHR de MAN, pendant votre permanence, alors que l'infirmier s'est retiré pour sa pause déjeuner, vous recevez monsieur Gbê. Voici les faits rapportés par celui-ci à l'interrogatoire : « Docteur, depuis près de dix jours je ne fais pas de selle ni de vent. En tout cas je sens un inconfort au ventre avec des douleurs vives. Vraiment docteur aidez-moi, ça ne va pas, je ne veux pas mourir ! » s'exclame-t-il tout en larmes.\",\n       \"text\": \"L'infirmier vous demande d'entamer la prise en charge médicale de M. Gbê. Indiquer les actes que vous pouvez poser parmi les propositions suivantes.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Prélèvement sanguin\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Pose d'une sonde nasogastrique\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Préparation physique du malade\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Installation du malade\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Prise d'une voie veineuse\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Préparation de la chambre du malade\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Prélèvement sanguin ; E. Prise d'une voie veineuse\",\n       \"answerLetters\": [\n        \"A\",\n        \"E\"\n       ],\n       \"explanation\": \"Gestes d'urgence du cours : prélever du sang (bilan électrolytique, groupage, NFS-hématocrite) et mettre en place une perfusion (voie veineuse) pour corriger les désordres hydroélectrolytiques. Préparation physique, installation et préparation de la chambre ne relèvent pas de la prise en charge médicale. Remarque : Le cours cite aussi la sonde gastroduodénale en aspiration parmi les gestes d'urgence.\\n\\nSource : licence 2 ide (Prise en charge infirmière des pathologies chirurgicales L2), Occlusions intestinales aiguës, p. 121-128 ; Cours de chirurgie traumatique et digestif, diapos 223-231 (VI Traitement, gestes d'urgence)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__26\",\n       \"num\": \"27\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE N°2. Stagiaire au CHR de MAN, pendant votre permanence, alors que l'infirmier s'est retiré pour sa pause déjeuner, vous recevez monsieur Gbê. Voici les faits rapportés par celui-ci à l'interrogatoire : « Docteur, depuis près de dix jours je ne fais pas de selle ni de vent. En tout cas je sens un inconfort au ventre avec des douleurs vives. Vraiment docteur aidez-moi, ça ne va pas, je ne veux pas mourir ! » s'exclame-t-il tout en larmes.\",\n       \"text\": \"Indiquer parmi ces propositions les actes infirmiers que vous pouvez réaliser avant l'arrivée de l'infirmier.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Pose d'une sonde nasogastrique\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Préparation physique du malade\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Installation du malade\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Prise d'une voie veineuse\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Prélèvement sanguin\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Préparation de la chambre du malade\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Préparation physique du malade ; E. Prélèvement sanguin ; F. Préparation de la chambre du malade\",\n       \"answerLetters\": [\n        \"B\",\n        \"E\",\n        \"F\"\n       ],\n       \"explanation\": \"En l'absence de l'infirmier, le stagiaire peut réaliser des actes simples et sans risque : préparation physique du malade, prélèvement sanguin prescrit et préparation de la chambre. La pose de sonde nasogastrique et de voie veineuse demande l'infirmier. Remarque : Le prélèvement sanguin est coché ici et la voie veineuse à la question 26 : les deux questions ne portent pas sur le même moment (avant / après l'arrivée de l'infirmier). (explication hors cours du projet)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__27\",\n       \"num\": \"28\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE N°2. Stagiaire au CHR de MAN, pendant votre permanence, alors que l'infirmier s'est retiré pour sa pause déjeuner, vous recevez monsieur Gbê. Voici les faits rapportés par celui-ci à l'interrogatoire : « Docteur, depuis près de dix jours je ne fais pas de selle ni de vent. En tout cas je sens un inconfort au ventre avec des douleurs vives. Vraiment docteur aidez-moi, ça ne va pas, je ne veux pas mourir ! » s'exclame-t-il tout en larmes.\",\n       \"text\": \"L'infirmier vous demande de préparer le champ opératoire. Indiquer l'ordre chronologique de cette préparation physique parmi ces propositions.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Détersion / Désinfection / Rasage\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Rasage / Détersion / Désinfection\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Détersion / Rasage / Désinfection\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Rasage / Désinfection / Détersion\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Détersion / Rasage / Désinfection\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Le cours décrit : préparation minutieuse de la peau (brossage, eau-savon = détersion), puis rasage large, puis grand savonnage et désinfection (alcool, Bétadine). Ordre : Détersion / Rasage / Désinfection. La désinfection se fait toujours en dernier, juste avant les champs stériles.\\n\\nSource : licence 2 ide, soins pré, per et postopératoires (fractures p. 47-50 ; péritonite p. 133-135) ; COURS PATHOLOGIE CHIRURGICALE (L2 2023), p. 37-39 (Préparer le champ opératoire)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__28\",\n       \"num\": \"29\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE N°2. Stagiaire au CHR de MAN, pendant votre permanence, alors que l'infirmier s'est retiré pour sa pause déjeuner, vous recevez monsieur Gbê. Voici les faits rapportés par celui-ci à l'interrogatoire : « Docteur, depuis près de dix jours je ne fais pas de selle ni de vent. En tout cas je sens un inconfort au ventre avec des douleurs vives. Vraiment docteur aidez-moi, ça ne va pas, je ne veux pas mourir ! » s'exclame-t-il tout en larmes.\",\n       \"text\": \"Le chirurgien décide de réaliser une laparotomie. Indiquer deux buts visés par le chirurgien en réalisant ce type d'intervention.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"But de poser une sonde d'aspiration\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"But de réaliser une hémostase\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"But de réaliser une endoscopie\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"But diagnostic\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"But thérapeutique\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"But de réaliser une ponction\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"D. But diagnostic ; E. But thérapeutique\",\n       \"answerLetters\": [\n        \"D\",\n        \"E\"\n       ],\n       \"explanation\": \"La laparotomie permet de faire le bilan à ventre ouvert et de reconnaître la lésion (but diagnostique), puis de lever l'obstacle (but thérapeutique : exérèse, dérivation, détorsion). Les autres propositions sont des gestes, pas des buts.\\n\\nSource : licence 2 ide (Prise en charge infirmière des pathologies chirurgicales L2), Occlusions intestinales aiguës, p. 121-128 ; Cours de chirurgie traumatique et digestif, diapos 223-231 (Occlusion du grêle : « laparotomie médiane permettant de faire le bilan à ventre ouvert, de reconnaître la lésion »)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__29\",\n       \"num\": \"30\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE N°2. Stagiaire au CHR de MAN, pendant votre permanence, alors que l'infirmier s'est retiré pour sa pause déjeuner, vous recevez monsieur Gbê. Voici les faits rapportés par celui-ci à l'interrogatoire : « Docteur, depuis près de dix jours je ne fais pas de selle ni de vent. En tout cas je sens un inconfort au ventre avec des douleurs vives. Vraiment docteur aidez-moi, ça ne va pas, je ne veux pas mourir ! » s'exclame-t-il tout en larmes.\",\n       \"text\": \"Indiquer les actes à accomplir dans la période peropératoire parmi les propositions ci-dessous.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Installer le matériel d'oxygénothérapie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Surveillance du pansement\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Favoriser le lever précoce\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Réfection du lit du malade\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Surveillance de drains\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Élaborer une fiche de surveillance\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Installer le matériel d'oxygénothérapie ; B. Surveillance du pansement ; D. Réfection du lit du malade\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"Pendant l'intervention, l'infirmier prépare la chambre : réfection du lit, préparation et vérification du matériel d'oxygénothérapie et d'aspiration. Le cours de L2 (ménisque, période peropératoire) cite aussi « pansement et drainage ». Le lever précoce est postopératoire. Remarque : Le cours cite aussi la feuille de surveillance parmi les préparatifs peropératoires (non cochée ici).\\n\\nSource : licence 2 ide, soins pré, per et postopératoires (fractures p. 47-50 ; péritonite p. 133-135) ; COURS PATHOLOGIE CHIRURGICALE (L2 2023), p. 37-39 (9.2.3 Soins peropératoires)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__30\",\n       \"num\": \"31\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE N°2. Stagiaire au CHR de MAN, pendant votre permanence, alors que l'infirmier s'est retiré pour sa pause déjeuner, vous recevez monsieur Gbê. Voici les faits rapportés par celui-ci à l'interrogatoire : « Docteur, depuis près de dix jours je ne fais pas de selle ni de vent. En tout cas je sens un inconfort au ventre avec des douleurs vives. Vraiment docteur aidez-moi, ça ne va pas, je ne veux pas mourir ! » s'exclame-t-il tout en larmes.\",\n       \"text\": \"Indiquer les actes à accomplir dans la période postopératoire de M. Gbê parmi les propositions ci-dessous.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Installer le matériel d'oxygénothérapie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Réfection du lit du malade\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Favoriser le lever précoce\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Élaborer une fiche de surveillance\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Surveillance de drains\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Surveillance du pansement\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Réfection du lit du malade ; D. Élaborer une fiche de surveillance ; E. Surveillance de drains\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\",\n        \"E\"\n       ],\n       \"explanation\": \"En postopératoire, le cours prévoit la surveillance des drains (Redon : vide, fixation, écoulement) et la tenue de la surveillance (constantes notées).\\n\\nSource : licence 2 ide, soins pré, per et postopératoires (fractures p. 47-50 ; péritonite p. 133-135) ; COURS PATHOLOGIE CHIRURGICALE (L2 2023), p. 37-39 (9.2.4 Soins postopératoires)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__31\",\n       \"num\": \"32\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE N°2. Stagiaire au CHR de MAN, pendant votre permanence, alors que l'infirmier s'est retiré pour sa pause déjeuner, vous recevez monsieur Gbê. Voici les faits rapportés par celui-ci à l'interrogatoire : « Docteur, depuis près de dix jours je ne fais pas de selle ni de vent. En tout cas je sens un inconfort au ventre avec des douleurs vives. Vraiment docteur aidez-moi, ça ne va pas, je ne veux pas mourir ! » s'exclame-t-il tout en larmes.\",\n       \"text\": \"Indiquer parmi ces propositions l'intérêt de surveiller le pansement et les drains.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Déceler une hémorragie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Prévenir les phlébites\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Prévenir le syndrome de Mendelson\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Prévenir les hémorragies\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Déceler une hémorragie\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Surveiller pansement et drains permet de déceler (dépister) une hémorragie : la surveillance ne prévient pas l'hémorragie, elle la repère. Les phlébites se préviennent par le lever précoce ; le syndrome de Mendelson par l'aspiration gastrique.\\n\\nSource : licence 2 ide, soins pré, per et postopératoires (fractures p. 47-50 ; péritonite p. 133-135) ; COURS PATHOLOGIE CHIRURGICALE (L2 2023), p. 37-39 (« surveillance locale du pansement → hémorragie par les redons »)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__32\",\n       \"num\": \"33\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"CAS CLINIQUE N°2. Stagiaire au CHR de MAN, pendant votre permanence, alors que l'infirmier s'est retiré pour sa pause déjeuner, vous recevez monsieur Gbê. Voici les faits rapportés par celui-ci à l'interrogatoire : « Docteur, depuis près de dix jours je ne fais pas de selle ni de vent. En tout cas je sens un inconfort au ventre avec des douleurs vives. Vraiment docteur aidez-moi, ça ne va pas, je ne veux pas mourir ! » s'exclame-t-il tout en larmes.\",\n       \"text\": \"Indiquer parmi ces propositions le phénomène qui témoigne de la réussite de l'intervention.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La perméabilité des drains\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Le réveil du malade\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"L'absence d'hémorragie\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La reprise du transit intestinal\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. La reprise du transit intestinal\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"L'intervention avait pour but de lever l'obstacle : la reprise du transit (gaz puis selles) prouve qu'il est levé. Le réveil, l'absence d'hémorragie et la perméabilité des drains témoignent seulement du bon déroulement des suites.\\n\\nSource : licence 2 ide, rôle postopératoire en chirurgie digestive (« la reprise du transit doit être guettée ») et péritonite (« jusqu'au rétablissement du transit »)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__33\",\n       \"num\": \"35\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Indiquer parmi ces propositions les deux signes que peut rapporter la victime en cas de fracture.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Une déformation\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Une mobilité anormale\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Une crépitation osseuse\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Une douleur vive\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Une impotence fonctionnelle\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Une mobilité anormale ; D. Une douleur vive\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"Ce que la victime rapporte (interrogatoire) = signes fonctionnels. La douleur vive en fait partie.\\n\\nSource : licence 2 ide, Fractures (p. 32-50) ; COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE, Généralités sur les fractures, p. 65-67\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__34\",\n       \"num\": \"36\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Indiquer parmi ces propositions trois signes que peut rechercher le praticien en cas de fracture.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Une impotence fonctionnelle\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Une mobilité anormale\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Une déformation\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Une douleur vive\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Une crépitation osseuse\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Une mobilité anormale ; C. Une déformation\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\"\n       ],\n       \"explanation\": \"Signes physiques recherchés à l'examen : déformation (inspection), mobilité anormale et crépitation osseuse (palpation). La douleur et l'impotence fonctionnelle sont des signes rapportés par la victime. Remarque : La question demande trois signes mais la correction n'en coche que deux ; le troisième signe physique du cours est la crépitation osseuse.\\n\\nSource : licence 2 ide, Fractures (p. 32-50) ; COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE, Généralités sur les fractures, p. 65-67\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__35\",\n       \"num\": \"37\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Indiquer la variété de déplacement qui traduit un chevauchement parmi ces propositions.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Déplacement rotatoire\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Déplacement transversal\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Déplacement longitudinal\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Déplacement angulaire\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Déplacement longitudinal\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Selon le cours : déplacement longitudinal = chevauchement ; transversal = baïonnette ; angulaire = angulation ; rotatoire = décalage.\\n\\nSource : licence 2 ide, Fractures (p. 32-50) ; COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE, Généralités sur les fractures, p. 65-67 (4.2 Le déplacement des fragments)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__36\",\n       \"num\": \"38\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Indiquer la variété de déplacement qui traduit le déplacement en baïonnette parmi ces propositions.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Déplacement longitudinal\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Déplacement rotatoire\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Déplacement transversal\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Déplacement angulaire\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Déplacement transversal\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Le déplacement transversal est le déplacement « en baïonnette » (les fragments glissent latéralement l'un par rapport à l'autre).\\n\\nSource : licence 2 ide, Fractures (p. 32-50) ; COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE, Généralités sur les fractures, p. 65-67 (4.2)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__37\",\n       \"num\": \"39\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Indiquer l'ordre chronologique de la prise en charge orthopédique d'une fracture.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Réduction / Rééducation / Contention\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Contention / Réduction / Rééducation\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Contention / Rééducation / Réduction\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Réduction / Contention / Rééducation\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Rééducation / Réduction / Contention\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Réduction / Contention / Rééducation\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Le traitement d'une fracture déplacée comporte la réduction (remettre les fragments en place), puis la contention (immobiliser pour permettre la consolidation) ; la rééducation vient ensuite pour récupérer la fonction.\\n\\nSource : COURS PATHOLOGIE CHIRURGICALE (L2 2023), V Traitement, principes généraux, p. 22\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__38\",\n       \"num\": \"40\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Indiquer parmi ces propositions l'examen de confirmation d'une fracture.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"L'ECG\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"L'échographie\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"L'EEG\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La radiographie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. La radiographie\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"« La radiographie seule permet de confirmer le diagnostic » (deux clichés, face et profil). ECG, échographie et EEG ne confirment pas une fracture.\\n\\nSource : licence 2 ide, Fractures (p. 32-50) ; COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE, Généralités sur les fractures, p. 65-67 (IV Examens complémentaires)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__39\",\n       \"num\": \"41\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Indiquer parmi ces propositions trois signes que peut mettre en évidence l'examen de confirmation d'une fracture.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Le déplacement des fragments osseux\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Les lésions associées\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Le type de fracture\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La déformation\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"La mobilité anormale\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"La crépitation osseuse\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Les lésions associées ; E. La mobilité anormale ; F. La crépitation osseuse\",\n       \"answerLetters\": [\n        \"B\",\n        \"E\",\n        \"F\"\n       ],\n       \"explanation\": \"La radiographie précise les lésions osseuses associées.\\n\\nSource : licence 2 ide, Fractures (p. 32-50) ; COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE, Généralités sur les fractures, p. 65-67 (IV Examens complémentaires : 4.1 type, 4.2 déplacement, 4.3 lésions associées)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__40\",\n       \"num\": \"42\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Indiquer les types de fractures parmi les propositions ci-dessous.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Fracture ouverte\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Fracture incomplète\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Fracture en bois vert\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Fracture fermée\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Fracture complète\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Fracture incomplète ; D. Fracture fermée\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"Le cours classe les fractures en complète / incomplète (selon le trait) et en fermée / ouverte (selon la communication avec l'extérieur). La fracture en bois vert est une variété de fracture incomplète (question 43). Remarque : « Fracture ouverte » et « fracture complète » sont aussi des types de fractures dans le cours ; la correction n'en retient que deux.\\n\\nSource : licence 2 ide, Fractures (p. 32-50) ; COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE, Généralités sur les fractures, p. 65-67 (4.1 Type de fracture ; V Différentes sortes de fractures)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__41\",\n       \"num\": \"43\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Indiquer une variété de fracture incomplète parmi ces propositions.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Fracture en bois vert\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Fracture simple\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Fracture comminutive\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Fracture à étage\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Fracture en bois vert\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Les fractures incomplètes avec flexion, fréquentes chez l'enfant, sont dites « en bois vert ». Fractures simple, à étage et comminutive sont des variétés de fractures complètes.\\n\\nSource : licence 2 ide, Fractures (p. 32-50) ; COURS PATHOLOGIE CHIRURGICALE SEMIOLOGIE, Généralités sur les fractures, p. 65-67 (4.1 b. Fracture incomplète)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__42\",\n       \"num\": \"44\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Relier chaque local du bloc opératoire à son destinataire. Locaux : A. Salle de réveil ; B. Salle d'eau ; C. Salle de stérilisation ; D. Salle d'hospitalisation. Destinataires : 1. Panseur ; 2. Malade ; 3. Chirurgien.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"(D, 3) / (B, 2) / (C, 1)\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"(A, 2) / (B, 3) / (C, 1)\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"(D, 1) / (C, 2) / (A, 3)\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"(B, 2) / (C, 2) / (A, 3)\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. (A, 2) / (B, 3) / (C, 1)\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Salle de réveil → malade (A-2) ; salle d'eau, où se fait le lavage chirurgical des mains → chirurgien (B-3) ; salle de stérilisation, où le panseur prépare le matériel → panseur (C-1). Les autres associations attribuent un même destinataire à deux locaux ou inversent les rôles. (explication hors cours du projet)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__43\",\n       \"num\": \"45\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Indiquer parmi ces propositions l'ordre chronologique de préparation d'un champ opératoire.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Détersion / rasage / désinfection\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Rasage / Détersion / désinfection\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Rasage / désinfection / Détersion\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Désinfection / rasage / Détersion\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Détersion / rasage / désinfection\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Même règle qu'à la question 28 : détersion (brossage eau-savon), rasage, puis désinfection antiseptique en dernier.\\n\\nSource : licence 2 ide, soins pré, per et postopératoires (fractures p. 47-50 ; péritonite p. 133-135) ; COURS PATHOLOGIE CHIRURGICALE (L2 2023), p. 37-39 (Préparer le champ opératoire)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__44\",\n       \"num\": \"46\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Indiquer parmi ces propositions le besoin prioritaire chez l'occlus du côlon.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Besoin d'éliminer\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Besoin de dormir et se reposer\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Besoin de manger et boire\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Besoin d'être propre, soigné et protéger ses téguments\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Besoin d'éliminer\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Dans l'occlusion du côlon, l'arrêt des matières et des gaz est net, les vomissements sont rares et l'état général longtemps conservé : le besoin perturbé en priorité est le besoin d'éliminer.\\n\\nSource : licence 2 ide (Prise en charge infirmière des pathologies chirurgicales L2), Occlusions intestinales aiguës, p. 121-128 ; Cours de chirurgie traumatique et digestif, diapos 223-231 (occlusion colique)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__45\",\n       \"num\": \"47\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Indiquer dans les suites opératoires deux avantages du lever précoce parmi ces propositions.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Accélère la reprise du transit\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Lutte contre l'infection\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Prévient les hémorragies\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Prévient les chocs hémodynamiques\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Prévient la stase et l'obstruction bronchique\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Favorise la cicatrisation\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Accélère la reprise du transit ; E. Prévient la stase et l'obstruction bronchique\",\n       \"answerLetters\": [\n        \"A\",\n        \"E\"\n       ],\n       \"explanation\": \"Le cours indique de « lutter contre l'atonie intestinale par le lever précoce » (reprise du transit) et d'assurer une bonne ventilation en luttant contre l'encombrement bronchique. Le lever précoce prévient aussi les phlébites et les escarres ; il ne lutte pas directement contre l'infection ou les hémorragies.\\n\\nSource : licence 2 ide, Péritonite, soins postopératoires (p. 134) ; Fractures, prévention des complications (p. 50)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__46\",\n       \"num\": \"48\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi ces gestes, deux peuvent être accomplis dans un établissement de premier contact par l'infirmier. Indiquez-les.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Pose d'une sonde nasogastrique\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Effectuer la prémédication\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Préparation du champ opératoire\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Établir une feuille d'évacuation\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Pose d'une voie veineuse\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Pose d'une sonde nasogastrique ; B. Effectuer la prémédication\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\"\n       ],\n       \"explanation\": \"Dans un établissement de premier contact, avant évacuation, l'infirmier peut poser une sonde nasogastrique (décompression digestive) et effectuer la prémédication prescrite. La préparation du champ opératoire se fait dans le service qui opère. Remarque : La prémédication n'est pas citée dans les cours du projet pour ce contexte (partie hors cours du projet).\\n\\nSource : licence 2 ide (Prise en charge infirmière des pathologies chirurgicales L2), Occlusions intestinales aiguës, p. 121-128 ; Cours de chirurgie traumatique et digestif, diapos 223-231 (gestes d'urgence : sonde gastroduodénale en aspiration)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__47\",\n       \"num\": \"49\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi ces propositions, indiquer le besoin prioritaire chez l'occlus du grêle.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Besoin d'éliminer\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Besoin de dormir et se reposer\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Besoin de respirer\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Besoin de manger et boire\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. Besoin de manger et boire\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Dans l'occlusion du grêle (haute), les vomissements sont précoces et abondants, l'intolérance gastrique est totale : le malade ne peut ni manger ni boire, d'où le besoin prioritaire de manger et boire (et le retentissement rapide sur l'état général).\\n\\nSource : licence 2 ide (Prise en charge infirmière des pathologies chirurgicales L2), Occlusions intestinales aiguës, p. 121-128 ; Cours de chirurgie traumatique et digestif, diapos 223-231 (V Diagnostic du siège)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__48\",\n       \"num\": \"50\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans l'occlusion intestinale, le lavement baryté s'effectue en cas de perforation intestinale.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux. Le lavement baryté est contre-indiqué en cas de perforation intestinale : la baryte passerait dans le péritoine et provoquerait une péritonite grave. Le cours le présente comme l'examen qui précise le siège d'un obstacle colique, pas comme un examen de la perforation. (explication hors cours du projet)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__49\",\n       \"num\": \"51\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans les occlusions intestinales hautes les vomissements sont tardifs alors qu'ils sont précoces dans les occlusions basses.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux : c'est l'inverse. Dans l'occlusion haute (grêle), les vomissements sont précoces et abondants ; dans l'occlusion basse (côlon), ils sont rares et tardifs.\\n\\nSource : licence 2 ide (Prise en charge infirmière des pathologies chirurgicales L2), Occlusions intestinales aiguës, p. 121-128 ; Cours de chirurgie traumatique et digestif, diapos 223-231 (V Diagnostic du siège)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__50\",\n       \"num\": \"52\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les occlusions hautes siègent au niveau du côlon et les occlusions basses au niveau du grêle.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux : les occlusions hautes siègent sur le grêle, les occlusions basses sur le côlon (le cours parle du cancer du côlon comme « facteur d'occlusion basse »).\\n\\nSource : licence 2 ide (Prise en charge infirmière des pathologies chirurgicales L2), Occlusions intestinales aiguës, p. 121-128 ; Cours de chirurgie traumatique et digestif, diapos 223-231\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__51\",\n       \"num\": \"53\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La péritonite se manifeste par une triade de signes fonctionnels et un signe physique.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai selon la correction nationale : la péritonite associe des signes fonctionnels (douleur abdominale brutale, vomissements, arrêt du transit) et un signe physique majeur, la contracture abdominale. Remarque : Dans les cours, la formule « trois signes fonctionnels et un signe physique » est écrite pour le syndrome occlusif ; pour la péritonite, le cours décrit la douleur et la contracture sans parler de triade.\\n\\nSource : licence 2 ide, Péritonites, p. 129-135 ; Cours de chirurgie traumatique et digestif, diapos 234-238\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__52\",\n       \"num\": \"54\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le signe physique de l'occlusion est la contracture abdominale alors que celui de la péritonite est le météorisme abdominal.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux : c'est l'inverse. Le signe physique de l'occlusion est le météorisme (« il n'y a jamais de contracture ») ; celui de la péritonite est la contracture abdominale.\\n\\nSource : licence 2 ide (Prise en charge infirmière des pathologies chirurgicales L2), Occlusions intestinales aiguës, p. 121-128 ; Cours de chirurgie traumatique et digestif, diapos 223-231 ; licence 2 ide, Péritonites, p. 129-135 ; Cours de chirurgie traumatique et digestif, diapos 234-238\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__53\",\n       \"num\": \"55\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La péritonite tuberculeuse est une péritonite secondaire.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux selon la correction nationale. Le cours classe la péritonite tuberculeuse parmi les péritonites chroniques ; elle est due au bacille de Koch qui atteint le péritoine, souvent par voie sanguine, et non à la perforation ou à l'infection d'un organe voisin, ce qui définit une péritonite secondaire.\\n\\nSource : licence 2 ide, Péritonites, p. 129-135 ; Cours de chirurgie traumatique et digestif, diapos 234-238 (3. Les péritonites chroniques)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__54\",\n       \"num\": \"56\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le ramassage de tous les traumatisés du rachis devra se faire à plusieurs et en monobloc avec maintien de l'axe cranio-rachidien.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai. Le cours interdit l'empoigne à deux (sous les aisselles et sous les genoux), qui peut déplacer une fracture du rachis et sectionner la moelle. Il faut maintenir le rachis en rectitude, relever en traction axiale et installer sur un plan dur, ce qui suppose plusieurs sauveteurs et un ramassage en monobloc.\\n\\nSource : licence 2 ide, Conduite à tenir auprès d'un traumatisé des voies publiques, p. 82-83 ; Cours de chirurgie traumatique et digestif, diapos 135-136\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__55\",\n       \"num\": \"57\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans la gastrectomie, le besoin de manger et boire peut trouver sa justification dans la modification anatomique de l'estomac.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai. Après une gastrectomie, l'estomac est réduit ou absent : la réalimentation est progressive (semi-liquide, puis normale vers le 7e jour en subtotale, le 10e en totale), et il faut fractionner les repas pour éviter malaises postprandiaux et diarrhée. C'est la modification anatomique qui perturbe le besoin de manger et boire.\\n\\nSource : licence 2 ide, Cancer de l'estomac, soins postopératoires, p. 145-146\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j2-ide__56\",\n       \"num\": \"58\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le besoin d'apprendre dans la colostomie peut se justifier par le caractère éducatif du soin pour le patient.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai. Le colostomisé doit apprendre à faire lui-même ses soins de stomie (changement de poche, soins de la peau, alimentation) : le soin a un caractère éducatif, ce qui justifie le besoin d'apprendre. (explication hors cours du projet)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J2 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      }\n     ]\n    }\n   ]\n  }\n ]\n}";
